CGALPoint cp1(p1.x(), p1.y(), p1.z());
CGALPoint cp2(p2.x(), p2.y(), p2.z());
CGALRay ray(cp1, cp2 - cp1);
std::vector<CGALTrianglePrimitive> intersected;
tree.intersect(ray, intersected);

int count = 0;
double max_t = (cp2 - cp1).squared_length();
for (const auto& primitive : intersected) {
    double t = primitive.intersection_parameter();
    if (t >= 0 && t <= 1.0) {
        count++;
    }
}
return count;

